import{z as A,x as B,o as E,c as p,q as o,j as i,D as t,d as r,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"缩放助推器","description":"","frontmatter":{"title":"缩放助推器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scaling-boosters.md","filePath":"litho/scaling-boosters.md","lastUpdated":1791413859000}'),d={name:"litho/scaling-boosters.md"};function h(m,a,D,P,C,F){const l=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=o('<h1 id="缩放助推器" tabindex="-1">缩放助推器 <a class="header-anchor" href="#缩放助推器" aria-label="Permalink to &quot;缩放助推器&quot;">​</a></h1><div class="epigraph"><p>节距不能再靠 $k_1$ 往下挖时，密度从结构来：埋入电源、接触上栅、自对准隔离一类助推器，改的是单元几何，不是再买一档 NA。</p><footer>—— 对照 imec 对 scaling boosters（BPR、CFET 前的单元助推）的公开路线图叙述</footer></div><p><a href="/litho/standard-cell-track-height">上一课</a>把轨高收成整数约束。缺口是：轨已经很少，仍要面积，就得把电源或接触从拥挤的中间层挪走。<a href="/litho/dtco-patterning">DTCO</a> 点过助推器；本课钉图形化含义。SRAM 如何单独玩一套几何，留给<a href="/litho/sram-cell-patterning">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缩放助推器（scaling boosters）是一组结构选项：埋入式电源轨（BPR / buried power rail）、接触上栅（contact over active gate）、自对准栅隔离、有时背面电源分配。它们让标准单元在同一金属节距下少占逻辑轨，或让 via 不再挤在栅与扩散的缝里。代价是新的关键层：深槽电源、高深宽比接触、背面套刻、以及新的硬掩模栈。</p><p><span class="marginnote">术语翻译：缩放助推器就是「不再向镜头要密度，改向单元结构要」的一组招式。BPR（埋入式电源轨）是把供电线埋进晶体管底下的沟槽，腾出上面最挤的金属层给信号线。</span></p><p>缺口是<strong>助推器引入哪些新图形化层</strong>，不是重讲器件纳米片。把助推器当「免费密度」会漏掉：深槽 ARDE、对准到埋入层、以及中间层金属反而更密带来的 tip 规则。</p><h3 id="不是每一助推器都是光刻问题" tabindex="-1">不是每一助推器都是光刻问题 <a class="header-anchor" href="#不是每一助推器都是光刻问题" aria-label="Permalink to &quot;不是每一助推器都是光刻问题&quot;">​</a></h3><p>有的密度来自器件堆叠（CFET）或背面互连，光刻只是其中一层对准与深孔。本课只写与前道光刻直接相关的：新掩模、新深宽比、新套刻对。CFET 与封装有自己的课，不在这里展开晶体管静电。</p><p><span class="marginnote">BPR 把电源从 M1 拿走，逻辑金属的可印性变好，但埋入槽的刻蚀与填充变成良率项。DTCO 必须把槽的 PWQ 算进节点，而不是只报单元面积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每一候选助推器列：新增层、节距、对准到谁、深宽比、是否自对准。用 LFD/LRC 评估：中间层热点是否真下降、新层是否可 PWQ。与 <a href="/litho/euv-sapt-hybrid">自对准</a> 的关系：能自对准的接触少吃套刻，助推器才划算；纯 LELE 去套一个埋入槽，预算可能比减轨省下的面积更贵。</p><p><span class="marginnote">直觉类比：评估助推器像买房验房——面积（密度）只是广告页，要查的是管线（新刻蚀层）、承重墙（对准树）和逃生通道（回退方案），一样不过就别签字。</span></p>',13)),(E(),i(n,null,{default:t(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E5%8A%A9%E6%8E%A8%E5%99%A8%22%5D%20--%3E%20LIST%5B%22%E5%88%97%E6%96%B0%E5%A2%9E%E5%B1%82%20%2F%20%E8%8A%82%E8%B7%9D%20%2F%20%E5%AF%B9%E5%87%86%20%2F%20%E6%B7%B1%E5%AE%BD%E6%AF%94%22%5D%0A%20%20LIST%20--%3E%20LFD%5B%22LFD%2FLRC%3A%20%E4%B8%AD%E9%97%B4%E5%B1%82%E7%83%AD%E7%82%B9%E7%9C%9F%E9%99%8D%3F%22%5D%0A%20%20LFD%20--%3E%20PWQ%5B%22%E6%96%B0%E5%B1%82%E5%8F%AF%20PWQ%3F%22%5D%0A%20%20PWQ%20--%3E%20FALL%5B%22%E6%9C%89%E5%9B%9E%E9%80%80%E8%B7%AF%E5%BE%84%3F%22%5D%0A%20%20FALL%20--%3E%7C%22%E6%9C%89%22%7C%20IN%5B%22%E5%85%81%E8%AE%B8%E8%BF%9B%E5%BA%93%22%5D%0A%20%20FALL%20--%3E%7C%22%E6%97%A0%22%7C%20OUT%5B%22%E4%B8%8D%E6%8A%8A%E8%8A%82%E7%82%B9%E6%8A%BC%E4%B8%8A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"评估输出是「允许进库的助推器集合」，不是宣传片上的百分比密度。",-1)),a[4]||(a[4]=e("p",null,"每个允许的助推器要带 PWQ 与对准树附件：深槽层对准到谁、标记如何开窗、失败时是否可回退到非埋入电源库。没有回退路径的助推器等于把节点赌在一条未鉴定的刻蚀上。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"单元面积 \\(\\approx\\) CPP × 轨高。助推器减小有效轨高或允许更紧的 CPP，但把难度转移到垂直加工：离子必须打到槽底，选择比与钝化变成主课序下一门的对象。套刻上，埋入层成为新的参考，对准标记与应力翘曲（后课）会改关键层策略。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"数字实例：CPP 100 nm、轨距 30 nm、5 轨高的单元约是 \\(100\\times 150\\ \\mathrm{nm}^2\\)。接触上栅若省掉 1 条轨，同一单元立省约 20% 面积——这笔账与 NA 无关，全靠结构换。")],-1)),(E(),i(n,null,{default:t(()=>[s(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E8%BD%A8%E9%AB%98%20%2F%20CPP%20%E6%92%9E%E5%A2%99%22%5D%20--%3E%20BPR%5B%22%E5%9F%8B%E5%85%A5%E7%94%B5%E6%BA%90%20%2F%20%E8%83%8C%E9%9D%A2%E4%BE%9B%E7%94%B5%22%5D%0A%20%20TH%20--%3E%20COAG%5B%22%E6%8E%A5%E8%A7%A6%E4%B8%8A%E6%A0%85%20%2F%20%E8%87%AA%E5%AF%B9%E5%87%86%22%5D%0A%20%20BPR%20--%3E%20NEW%5B%22%E6%96%B0%E6%B7%B1%E6%A7%BD%E4%B8%8E%E5%AF%B9%E5%87%86%22%5D%0A%20%20COAG%20--%3E%20NEW%0A%20%20NEW%20--%3E%20Y%5B%22%E8%BD%AC%E5%8D%B0%E4%B8%8E%E8%89%AF%E7%8E%87%E8%B4%A6%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某逻辑节点未公开的 BPR 尺寸。不把助推器写成大模型或量化金融。背面供电的封装/衬底工艺只点名套刻，细节留给集成课的对准与形貌。</p><p>后课默认：密度助推器是新关键层，不是免费的规则放松。下一课 SRAM 有自己的助推与多图形约束，不能直接套逻辑轨高。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缩放助推器用结构换密度，并新增深槽、对准与硬掩模层。</li><li>中间层热点下降必须用新层的窗口来买单。</li><li>自对准决定套刻账是否划算。</li><li>出处：imec scaling booster / BPR 公开论述；DTCO 路线图叙述。</li></ul>',5))])}const f=A(d,[["render",h]]);export{u as __pageData,f as default};
